"""
Parses the raw combined stdout+stderr of a single Lox benchmark script run
into a plain, uninterpreted list of (label, value) pairs.

No benchmark-specific logic lives here: every numeric line found is recorded,
in order, alongside whatever non-numeric line immediately preceded it (if
any). Nothing is dropped or picked out as "the" result -- if a benchmark
prints three numbers, all three are stored.

Example, for equality.lox's typical output:
    loop
    1.3697
    elapsed
    1.27907
    equals
    -0.09063

parse_output(...) returns:
    entries = [
        {"label": "loop", "value": 1.3697},
        {"label": "elapsed", "value": 1.27907},
        {"label": "equals", "value": -0.09063},
    ]
    error = None

If the run produced interpreter errors (e.g. clox's known 256-constant limit)
and no usable numbers, `error` is set to a short message instead.
"""

import re

FLOAT_RE = re.compile(r"^[+-]?(\d+\.\d*|\.\d+|\d+)([eE][+-]?\d+)?$")
ERROR_RE = re.compile(r"^\[line \d+\] Error")


def _is_float(line):
    return bool(FLOAT_RE.match(line.strip()))


def parse_output(text):
    """Parse the raw output of one benchmark run.

    Returns {"entries": [{"label": str|None, "value": float}, ...], "error": str|None}
    """
    entries = []
    last_label = None
    error_lines = []

    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        if ERROR_RE.match(line):
            error_lines.append(line)
            continue
        if _is_float(line):
            entries.append({"label": last_label, "value": float(line)})
            last_label = None
        else:
            if line.lower() not in ("true", "false"):
                last_label = line
            # else: sanity-check boolean prints aren't metric labels

    if not entries:
        if error_lines:
            uniq = sorted(set(error_lines))
            msg = uniq[0]
            if len(uniq) > 1:
                msg += f" (+{len(uniq) - 1} more distinct error message(s))"
            return {"entries": [], "error": msg}
        return {"entries": [], "error": "no numeric output captured"}

    return {"entries": entries, "error": None}
